278:                             return util.asArray(style)
279:                                 .map(formatProperty)
280:                                 .join('; ') + ';';
281: 
282:                             function formatProperty(name) {
283:                                 return name + ': ' +
284:                                     style.getPropertyValue(name) +
285:                                     (style.getPropertyPriority(name) ? ' !important' : '');
286:                             }
287:                         }
288:                     }
289:                 }
290:             }
