297:             function fixSvg() {
298:                 if (!(clone instanceof SVGElement)) return;
299:                 clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
300: 
301:                 if (!(clone instanceof SVGRectElement)) return;
302:                 ['width', 'height'].forEach(function (attribute) {
