375:             return {
376:                 'woff': WOFF,
377:                 'woff2': WOFF,
378:                 'ttf': 'application/font-truetype',
379:                 'eot': 'application/vnd.ms-fontobject',
380:                 'png': 'image/png',
381:                 'jpg': JPEG,
382:                 'jpeg': JPEG,
383:                 'gif': 'image/gif',
384:                 'tiff': 'image/tiff',
385:                 'svg': 'image/svg+xml'
