499:                         return;
500:                     }
501: 
502:                     var encoder = new FileReader();
503:                     encoder.onloadend = function () {
504:                         var content = encoder.result.split(/,/)[1];
505:                         resolve(content);
506:                     };
507:                     encoder.readAsDataURL(request.response);
508:                 }
